    quiz: { prompt: "Comment dit-on « j'étudie en Chine » ?", promptEn: "How do you say « I study in China »?", choices: ["我学习在中国", "我在中国学习", "我是中国学习", "我中国在学习"], correctChoiceIndex: 1 }
