    quiz: { prompt: "Comment dit-on « Je ne suis pas aussi grand que lui » ?", promptEn: "How do you say “I am not as tall as him”?", choices: ["我没有他高", "我不比他高", "我比他不高", "我比他很高"], correctChoiceIndex: 0 }
