    quiz: { prompt: "Quelle phrase est correcte ?", promptEn: "Which sentence is correct?", choices: ["所以我不去，因为下雨", "因为我不去，所以下雨", "我不去，由于下雨", "我不去，因为下雨"], correctChoiceIndex: 3 }
