    quiz: { prompt: "Où se place un complément de lieu introduit par 在 ?", promptEn: "Where does a place phrase with 在 go?", choices: ["Après le verbe", "À la fin de la phrase", "Entre le sujet et le verbe", "Avant le sujet uniquement"], correctChoiceIndex: 2 }
