    quiz: { prompt: "Où placer une durée comme trois heures de temps ?", promptEn: "Where do you put a duration such as three hours?", choices: ["Avant le sujet", "Entre le sujet et le verbe", "Après le verbe", "Au tout début de la phrase"], correctChoiceIndex: 2 }
