    quiz: { prompt: "Comment nier « Je suis en train de manger » ?", promptEn: "How do you negate « I am eating right now »?", choices: ["我不在吃饭", "我不吃饭在", "我在不吃饭", "我没在吃饭"], correctChoiceIndex: 3 }
