    quiz: { prompt: "Comment dire « J'ai étudié le chinois pendant deux ans » ?", promptEn: "How do you say « I studied Chinese for two years »?", choices: ["我两年学了中文", "我学了中文两年", "我学了两年中文", "两年我学中文了"], correctChoiceIndex: 2 }
