    quiz: { prompt: "Quelle phrase dit correctement « Dès qu'il est rentré, il s'est couché » ?", promptEn: "Which sentence correctly says \"As soon as he got home, he went to bed\"?", choices: ["他一回家就睡觉了", "他一回家睡觉了", "他一边回家一边睡觉", "他一回家了就睡觉"], correctChoiceIndex: 0 }
