    quiz: { prompt: "除了他，我们 ___ 同意 = « À part lui, nous sommes tous d'accord »", promptEn: "除了他，我们 ___ 同意 = “Apart from him, we all agree”", choices: ["都", "还", "也", "不"], correctChoiceIndex: 0 }
