    quiz: { prompt: "Comment dire « Il n'a même pas regardé » ?", promptEn: "How do you say \"He didn't even look\"?", choices: ["他没看", "他连看都没看", "他连没看", "他都看没有"], correctChoiceIndex: 1 }
