    quiz: { prompt: "Ton ami dort en ce moment et tu décris la scène : quelle phrase décrit un ÉTAT qui dure ?", promptEn: "Which sentence describes a STATE that lasts?", choices: ["我正在吃饭", "我吃了饭", "门开着", "我会吃饭"], correctChoiceIndex: 2 }
