    quiz: { prompt: "Laquelle de ces phrases est INCORRECTE ?", promptEn: "Which of these sentences is INCORRECT?", choices: ["天气逐渐变冷了", "你逐渐吃，别着急", "经济正在逐渐恢复", "他逐渐习惯了新生活"], correctChoiceIndex: 1 }
