    quiz: { prompt: "Il a plu trois jours d'affilée, sans interruption. Quel mot choisir ?", promptEn: "It rained three days straight, without a break. Which word do you choose?", choices: ["陆续", "连续", "继续", "相继"], correctChoiceIndex: 1 }
