    quiz: { prompt: "Tu veux nuancer un compliment sans vexer ton interlocuteur. Quel connecteur choisis-tu ?", promptEn: "You want to soften a compliment without offending. Which connector do you pick?", choices: ["然而", "不过", "因此", "于是"], correctChoiceIndex: 1 }
