    quiz: { prompt: "Où se place 的话 dans une phrase conditionnelle ?", promptEn: "Where does 的话 go in a conditional sentence?", choices: ["Tout au début de la phrase, comme « si »", "À la fin de la proposition qui exprime la condition", "À la fin de la proposition qui exprime le résultat", "Juste après le verbe principal du résultat"], correctChoiceIndex: 1 }
