    quiz: { prompt: "Où se place 都 dans la phrase ?", promptEn: "Where does 都 go in the sentence?", choices: ["Avant le sujet", "Après le sujet, juste avant le verbe", "Après le verbe", "À la fin de la phrase"], correctChoiceIndex: 1 }
