    quiz: { prompt: "Quelle phrase est correcte ?", promptEn: "Which sentence is correct?", choices: ["一边他吃饭一边看电视", "他一边吃饭一边看电视", "他一边吃饭，她一边看电视", "他一边是学生一边工作"], correctChoiceIndex: 1 }
