    quiz: { prompt: "Comment dit-on « Je téléphone à maman » ?", promptEn: "How do you say “I phone my mum”?", choices: ["我给妈妈打电话", "我打电话给妈妈了吗", "我打给电话妈妈", "我妈妈给打电话"], correctChoiceIndex: 0 }
