    quiz: { prompt: "Les deux sujets sont différents (le professeur, puis les élèves). Quelle phrase est correcte ?", promptEn: "The two subjects are different (the teacher, then the students). Which sentence is correct?", choices: ["老师不仅同意了，而且学生也同意了", "不仅老师同意了，而且学生也同意了", "老师同意了不仅，学生也同意了而且", "不仅老师同意了，但是学生也同意了"], correctChoiceIndex: 1 }
