    quiz: { prompt: "Quelle phrase exprime une condition SUFFISANTE (il suffit de) et non nécessaire ?", promptEn: "Which sentence expresses a SUFFICIENT condition (it's enough to) rather than a necessary one?", choices: ["只有努力才能成功", "只要努力就能成功", "除非努力，否则不能成功", "无论努力不努力都能成功"], correctChoiceIndex: 1 }
