    quiz: { prompt: "Pour dire « de Paris à Pékin » :", promptEn: "To say \"from Paris to Beijing\":", choices: ["离巴黎到北京", "从巴黎离北京", "从巴黎到北京", "到巴黎从北京"], correctChoiceIndex: 2 }
