    quiz: { prompt: "« Il éclate de rire » (soudain) =", promptEn: "\"He bursts out laughing\" (suddenly) =", choices: ["他笑出来", "他笑下去", "他笑下来", "他笑起来"], correctChoiceIndex: 3 }
