    quiz: { prompt: "Structure \"préférer X, quitte à ne pas Y\"", promptEn: "The pattern for \"prefer X, even if it means not Y\"", choices: ["虽然...但是", "与其...不如", "宁可...也不", "因为...所以"], correctChoiceIndex: 2 }
