for (const s of GRAMMAR_SHEETS) (SHEETS_BY_LEVEL[s.level] ??= []).push(s);
export const SHEET_LEVELS = Object.keys(SHEETS_BY_LEVEL).sort();

// ─── Familles grammaticales ──────────────────────────────────────────────────

/**
 * Une liste de 84 fiches rangées par seul niveau se parcourt à l'aveugle :
 * rien ne dit que 不 et 没 traitent du même problème, ni que 吗 et 呢 se
 * répondent. Les familles regroupent ce qui s'apprend ensemble, et se
 * déduisent du hanzi de la fiche — aucune donnée à saisir à la main, aucun
 * risque d'oublier de classer une fiche ajoutée plus tard.
 */
export type GrammarFamily =
  | 'negation' | 'question' | 'particle' | 'time' | 'quantity'
  | 'comparison' | 'connector' | 'structure';

/** Ordre d'affichage : du plus structurant au plus fin. */
export const GRAMMAR_FAMILIES: GrammarFamily[] = [
  'structure', 'negation', 'question', 'particle',
  'time', 'quantity', 'comparison', 'connector',
];

/** Motifs cherchés dans le hanzi de la fiche, puis dans sa traduction. */
const FAMILY_RULES: { family: GrammarFamily; hanzi: RegExp; fr?: RegExp }[] = [
  { family: 'negation',   hanzi: /不|没|别|无|非|未/, fr: /négat|ne pas|sans/i },
  { family: 'question',   hanzi: /吗|呢|什么|谁|哪|几|多少|怎么|为什么|吧|难道/,
                          fr: /interrogat|question|combien|comment|pourquoi|quoi|qui\b|où/i },
  { family: 'particle',   hanzi: /^的|^了|^着|^过|^地|^得|助词|结构助词/,
                          fr: /particule|aspect|complément de degré/i },
  { family: 'time',       hanzi: /时间|以前|以后|的时候|正在|快要|就要|已经|才|刚|从…到|年|月|日|点/,
                          fr: /temps|durée|moment|avant|après|déjà|bientôt|fréquence/i },
  { family: 'quantity',   hanzi: /量词|二|两|都|也|一点|有点|些|每|多|少|半|次|遍/,
                          fr: /quantit|classificateur|spécificatif|tous|aussi|un peu|chaque|nombre/i },
  { family: 'comparison', hanzi: /比|一样|最|更|不如|越…越|跟.*一样/,
                          fr: /compar|plus que|aussi.*que|le plus|superlatif/i },
  { family: 'connector',  hanzi: /因为|所以|虽然|但是|可是|如果|要是|不但|而且|还是|或者|然后|于是|因此/,
                          fr: /connect|cause|conséquence|opposition|condition|hypoth|mais|donc|si\b/i },
];

/** Famille d'une fiche. `structure` est le fourre-tout assumé : phrases en 是, 有, 把, 被, ordre des mots. */
export function familyOf(sheet: GrammarSheet): GrammarFamily {
  const h = sheet.hanzi ?? '';
  const fr = sheet.translationFr ?? '';
  for (const r of FAMILY_RULES) if (r.hanzi.test(h)) return r.family;
  for (const r of FAMILY_RULES) if (r.fr?.test(fr)) return r.family;
  return 'structure';
}
